const now    = new Date();
const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
return [{
  json: {
    since: sevenDaysAgo.toISOString(),
    until: now.toISOString(),
    weekLabel: `Week of ${sevenDaysAgo.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' })}–${now.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' })}`
  }
}];

const since = new Date($json.since);
const weekLabel = $json.weekLabel;

// Paginate through the full collection
let allPoints = [];
let offset = null;
const pageSize = 100;

do {
  const body = { limit: pageSize, with_payload: true };
  if (offset) body.offset = offset;

  const resp = await fetch('http://qdrant:6333/collections/arxiv_papers/points/scroll', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'api-key': $vars.QDRANT_API_KEY || ''
    },
    body: JSON.stringify(body)
  });

  if (!resp.ok) {
    const err = await resp.text();
    throw new Error(`Qdrant scroll failed: ${err}`);
  }

  const data = await resp.json();
  const points = data.result?.points || [];
  allPoints = allPoints.concat(points);
  offset = data.result?.next_page_offset || null;
} while (offset);

// Extract metadata and filter to papers from the last 7 days
// Fall back to all points if ingested_at is not set (older points)
const papers = allPoints
  .map(p => ({
    title:         p.payload?.metadata?.title         || p.payload?.title         || 'Untitled',
    url:           p.payload?.metadata?.url           || p.payload?.url           || '',
    tags:          p.payload?.metadata?.tags          || p.payload?.tags          || [],
    relevance:     p.payload?.metadata?.relevance     || p.payload?.relevance     || 'Unknown',
    what_it_does:  p.payload?.metadata?.what_it_does  || p.payload?.what_it_does  || '',
    why_it_matters:p.payload?.metadata?.why_it_matters|| p.payload?.why_it_matters|| '',
    ingested_at:   p.payload?.metadata?.ingested_at   || p.payload?.ingested_at   || null,
    user_rating:   p.payload?.metadata?.user_rating   || p.payload?.user_rating   || 0
  }))
  .filter(p => {
    if (!p.ingested_at) return false;
    return new Date(p.ingested_at) >= since;
  });

if (papers.length === 0) {
  throw new Error('NO_PAPERS_THIS_WEEK');
}

return [{ json: { papers, weekLabel, total: papers.length } }];

const { papers, weekLabel, total } = $json;

// Group papers by their first tag; untagged go to 'Other'
const groups = {};
for (const paper of papers) {
  const tagList = Array.isArray(paper.tags) ? paper.tags : [];
  const primaryTag = tagList[0] || 'Other';
  if (!groups[primaryTag]) groups[primaryTag] = [];
  groups[primaryTag].push(paper);
}

// Sort groups by paper count descending
const sortedGroups = Object.entries(groups)
  .sort((a, b) => b[1].length - a[1].length)
  .map(([tag, papers]) => ({ tag, papers }));

// Flag saved papers (user_rating: 1) for top-3 picks
const savedPapers = papers
  .filter(p => p.user_rating === 1)
  .slice(0, 3);

// High-relevance papers for top picks if no saved ones
const highPapers = papers
  .filter(p => p.relevance === 'High' && p.user_rating !== -1)
  .slice(0, 3);

const topPicks = savedPapers.length > 0 ? savedPapers : highPapers;

return [{ json: { groups: sortedGroups, topPicks, weekLabel, total } }];

