const raw = $json.choices?.[0]?.message?.content || '{}';

let digest;
try {
  digest = JSON.parse(raw);
} catch (e) {
  throw new Error(`GPT-4o returned non-JSON: ${raw.slice(0, 200)}`);
}

const weekLabel = $('Group by Tag').first().json.weekLabel;
const total     = $('Group by Tag').first().json.total;

const lines = [
  `📰 *ResearchFlow Weekly Digest*`,
  `_${weekLabel} · ${total} papers indexed_`,
  '',
  `🌐 *This week's trend:* ${digest.overall_trend || ''}`,
  ''
];

// Group narratives
for (const g of (digest.group_narratives || [])) {
  lines.push(`🏷️ *${g.tag}*`);
  lines.push(g.narrative || '');
  lines.push('');
}

// Top 3 picks
if (digest.top_3_picks?.length > 0) {
  lines.push('⭐ *Papers of the week*');
  digest.top_3_picks.forEach((p, i) => {
    lines.push(`${i + 1}. *${p.title}*`);
    lines.push(`   _${p.reason}_`);
  });
  lines.push('');
}

lines.push('_Use /search to ask questions about any of these papers._');

return [{ json: { text: lines.join('\n'), weekLabel, total } }];
